80	static int32_t dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)
81	{
82	    lv_draw_epic_unit_t * draw_epic_unit = (lv_draw_epic_unit_t *) draw_unit;
83	
84	    /* Try to get an idle task */
85	    lv_draw_task_t * t = NULL;
86	    t = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_EPIC);
87	    if(t == NULL) return -1;
88	
89	    /* If the task is not supported by EPIC, return -1 to let SW handle it */
90	    if(t->type != LV_DRAW_TASK_TYPE_FILL &&
91	       t->type != LV_DRAW_TASK_TYPE_IMAGE) {
92	        return -1;
93	    }
94	
95	    /* Mark the task as in progress */
96	    lv_draw_task_t * task = t;
97	    task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
98	
99	    /* Execute the task */
100	    draw_epic_unit->task_act = task;
101	
102	    /* For now, just mark as ready - actual EPIC operations will be added later */
103	    task->state = LV_DRAW_TASK_STATE_READY;
104	    draw_epic_unit->task_act = NULL;
105	
106	    return 1;
107	}
108	
109	static int32_t evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * task)
110	{
111	    LV_UNUSED(draw_unit);
112	
113	    /* Only support fill tasks for now */
114	    if(task->type == LV_DRAW_TASK_TYPE_FILL) {
115	        /* Check if the area is large enough to benefit from GPU */
116	        int32_t w = lv_area_get_width(&task->area);
117	        int32_t h = lv_area_get_height(&task->area);
118	        if(w * h > 1000) { /* Only use GPU for larger areas */
119	            return 100; /* Higher priority than SW */
120	        }
121	    }
122	
123	    return 0; /* Don't handle */
124	}
125	
126	static int32_t lv_draw_epic_delete(lv_draw_unit_t * draw_unit)
127	{
128	    LV_UNUSED(draw_unit);
129	    return 1;
130	}
