     /**
      * @file lv_draw_epic.c
      *
      * EPIC GPU draw unit for LVGL - hardware accelerated rendering
      *
      * SPDX-FileCopyrightText: 2024 SiFli Technologies
      * SPDX-License-Identifier: Apache-2.0
