     #include "lv_draw_epic.h"

     #if LV_USE_DRAW_EPIC

     #include "../lv_draw.h"
     #include "../../display/lv_display_private.h"
     #include "../../stdlib/lv_string.h"
     #include "../../core/lv_global.h"

     #include <string.h>

     #include "drv_epic.h"

     #define DRAW_UNIT_ID_EPIC 5

     typedef struct _lv_draw_epic_unit_t {
         lv_draw_unit_t base_unit;
         lv_draw_task_t *task_act;
     } lv_draw_epic_unit_t;

     static int32_t dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer);
     static int32_t evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * task);
     static int32_t lv_draw_epic_delete(lv_draw_unit_t * draw_unit);
     static void execute_fill(lv_draw_task_t * task);
     static void execute_image(lv_draw_task_t * task);

     void lv_draw_epic_init(void)
     {
         lv_draw_epic_unit_t * draw_epic_unit = lv_draw_create_unit(sizeof(lv_draw_epic_unit_t));
         draw_epic_unit->base_unit.dispatch_cb = dispatch;
         draw_epic_unit->base_unit.evaluate_cb = evaluate;
         draw_epic_unit->base_unit.delete_cb = lv_draw_epic_delete;
         drv_gpu_open();
     }

     void lv_draw_epic_deinit(void)
     {
         drv_gpu_close();
     }

     static int32_t dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)
     {
         lv_draw_epic_unit_t * draw_epic_unit = (lv_draw_epic_unit_t *) draw_unit;
         lv_draw_task_t * t = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_EPIC);
         if(t == NULL) return -1;
         if(t->type != LV_DRAW_TASK_TYPE_FILL && t->type != LV_DRAW_TASK_TYPE_IMAGE) {
             return -1;
         }
         lv_draw_task_t * task = t;
         task->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
         draw_epic_unit->task_act = task;
         switch(task->type) {
             case LV_DRAW_TASK_TYPE_FILL:
                 execute_fill(task);
                 break;
             case LV_DRAW_TASK_TYPE_IMAGE:
                 execute_image(task);
                 break;
             default:
                 break;
         }
         task->state = LV_DRAW_TASK_STATE_READY;
         draw_epic_unit->task_act = NULL;
         return 1;
     }

     static int32_t evaluate(lv_draw_unit_t * draw_unit, lv_draw_task_t * task)
     {
         LV_UNUSED(draw_unit);
         if(task->type == LV_DRAW_TASK_TYPE_FILL) {
             int32_t w = lv_area_get_width(&task->area);
             int32_t h = lv_area_get_height(&task->area);
             if(w * h > 100) { return 100; }
         }
         if(task->type == LV_DRAW_TASK_TYPE_IMAGE) {
             int32_t w = lv_area_get_width(&task->area);
             int32_t h = lv_area_get_height(&task->area);
             if(w * h > 100) { return 100; }
         }
         return 0;
     }

     static int32_t lv_draw_epic_delete(lv_draw_unit_t * draw_unit)
     {
         LV_UNUSED(draw_unit);
         return 1;
     }

     static void execute_fill(lv_draw_task_t * task)
     {
         lv_draw_fill_dsc_t * dsc = task->draw_dsc;
         if(dsc == NULL) return;
         EPIC_LayerConfigTypeDef input_layers[1];
         EPIC_LayerConfigTypeDef output_layer;
         memset(input_layers, 0, sizeof(input_layers));
         memset(&output_layer, 0, sizeof(output_layer));
         lv_display_t * disp = lv_display_get_default();
         if(disp == NULL) return;
         int32_t w = lv_area_get_width(&task->area);
         int32_t h = lv_area_get_height(&task->area);
         output_layer.data = disp->buf_act->data;
         output_layer.width = w;
         output_layer.height = h;
         output_layer.total_width = w;
         output_layer.x_offset = task->area.x1;
         output_layer.y_offset = task->area.y1;
         output_layer.color_mode = EPIC_INPUT_ARGB8888;
         output_layer.alpha = 0xFF;
         input_layers[0].data = NULL;
         input_layers[0].width = w;
         input_layers[0].height = h;
         input_layers[0].total_width = w;
         input_layers[0].x_offset = 0;
         input_layers[0].y_offset = 0;
         input_layers[0].color_mode = EPIC_INPUT_ARGB8888;
         input_layers[0].alpha = 0xFF;
         lv_color_t color = dsc->color;
         input_layers[0].color_en = true;
         input_layers[0].color_r = color.red;
         input_layers[0].color_g = color.green;
         input_layers[0].color_b = color.blue;
         int ret = drv_epic_fill_ext(input_layers, 1, &output_layer, NULL);
         if(ret != 0) {
             LV_LOG_WARN("EPIC fill failed, falling back to SW");
         }
     }

     static void execute_image(lv_draw_task_t * task)
     {
         lv_draw_image_dsc_t * dsc = task->draw_dsc;
         if(dsc == NULL) return;
         const lv_draw_buf_t * draw_buf = dsc->src;
         if(draw_buf == NULL) return;
         EPIC_LayerConfigTypeDef input_layers[1];
         EPIC_LayerConfigTypeDef output_layer;
         memset(input_layers, 0, sizeof(input_layers));
         memset(&output_layer, 0, sizeof(output_layer));
         lv_display_t * disp = lv_display_get_default();
         if(disp == NULL) return;
         int32_t w = lv_area_get_width(&task->area);
         int32_t h = lv_area_get_height(&task->area);
         output_layer.data = disp->buf_act->data;
         output_layer.width = w;
         output_layer.height = h;
         output_layer.total_width = w;
         output_layer.x_offset = task->area.x1;
         output_layer.y_offset = task->area.y1;
         output_layer.color_mode = EPIC_INPUT_ARGB8888;
         output_layer.alpha = 0xFF;
         input_layers[0].data = (uint8_t *)draw_buf->data;
         input_layers[0].width = w;
         input_layers[0].height = h;
         input_layers[0].total_width = w;
         input_layers[0].x_offset = 0;
         input_layers[0].y_offset = 0;
         input_layers[0].color_mode = EPIC_INPUT_ARGB8888;
         input_layers[0].alpha = 0xFF;
         int ret = drv_epic_blend(input_layers, 1, &output_layer, NULL);
         if(ret != 0) {
             LV_LOG_WARN("EPIC blend failed, falling back to SW");
         }
     }

